        { q: "According to research, what is true of teams that never disagree?", options: ["They always succeed", "They often produce weaker work", "They finish faster", "They have better leaders"], answer: 1 },
        { q: "What is suggested about handling disagreement?", options: ["Avoid all discussion", "Let the leader decide everything", "Discuss the problem, not the person", "Leave the group immediately"], answer: 2 }
