        { q: "What do environmental teachers think of the critics' argument?", options: ["They agree individual efforts are useless", "They believe only laws matter", "They think both personal habits and laws are necessary", "They ignore the criticism"], answer: 2 },
        { q: "What is the message for college students in the last sentence?", options: ["Wait until they have power", "Start with small choices they can already make", "Leave the problem to factories", "Study environmental science first"], answer: 1 }
